import{_ as I,o as t,c as l,a0 as a}from"./chunks/framework.DQOulFGV.js";const e="data:image/svg+xml;base64,",d="data:image/svg+xml;base64,",r=JSON.parse('{"title":"第2章 哨兵模式","description":"","frontmatter":{},"headers":[],"relativePath":"redis/04-high-availability/chapter-02-sentinel.md","filePath":"redis/04-high-availability/chapter-02-sentinel.md"}'),s={name:"redis/04-high-availability/chapter-02-sentinel.md"};function g(h,i,m,Z,n,M){return t(),l("div",null,[...i[0]||(i[0]=[a('<h1 id="第2章-哨兵模式" tabindex="-1">第2章 哨兵模式 <a class="header-anchor" href="#第2章-哨兵模式" aria-label="Permalink to &quot;第2章 哨兵模式&quot;">​</a></h1><blockquote><p>主从复制需要手动切换主节点，哨兵（Sentinel）补上了「自动故障转移」这一环。本章讲解哨兵的职责、故障转移流程与局限。</p></blockquote><hr><h2 id="_2-1-三件职责" tabindex="-1">2.1 三件职责 <a class="header-anchor" href="#_2-1-三件职责" aria-label="Permalink to &quot;2.1 三件职责&quot;">​</a></h2><p>哨兵是一个独立的进程，负责监控主从节点，并在主节点故障时自动完成切换。</p><p><img src="'+e+'" alt="哨兵集群监控架构"></p><p>哨兵的三件职责：</p><table tabindex="0"><thead><tr><th style="text-align:left;">职责</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">监控</td><td style="text-align:left;">周期性检测主从节点是否存活</td></tr><tr><td style="text-align:left;">通知</td><td style="text-align:left;">节点故障时通知管理员或其他程序</td></tr><tr><td style="text-align:left;">自动故障转移</td><td style="text-align:left;">主节点故障时，选新主并让其他从节点跟随</td></tr></tbody></table><hr><h2 id="_2-2-故障转移流程" tabindex="-1">2.2 故障转移流程 <a class="header-anchor" href="#_2-2-故障转移流程" aria-label="Permalink to &quot;2.2 故障转移流程&quot;">​</a></h2><p>故障转移分为四个阶段：</p><p><img src="'+d+`" alt="哨兵故障转移流程"></p><h3 id="主观下线与客观下线" tabindex="-1">主观下线与客观下线 <a class="header-anchor" href="#主观下线与客观下线" aria-label="Permalink to &quot;主观下线与客观下线&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">阶段</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">主观下线（SDOWN）</td><td style="text-align:left;">单个哨兵发现主节点超时无响应，主观认为下线</td></tr><tr><td style="text-align:left;">客观下线（ODOWN）</td><td style="text-align:left;">多个哨兵（达到 quorum）都认为主节点下线，客观确认</td></tr></tbody></table><p>单个哨兵判断下线可能是误判（网络抖动），多个哨兵达成一致才可靠。</p><h3 id="选举领头哨兵" tabindex="-1">选举领头哨兵 <a class="header-anchor" href="#选举领头哨兵" aria-label="Permalink to &quot;选举领头哨兵&quot;">​</a></h3><p>客观下线后，哨兵之间通过类 Raft 的共识算法选举出一个「领头哨兵」，由它负责执行故障转移。</p><h3 id="执行故障转移" tabindex="-1">执行故障转移 <a class="header-anchor" href="#执行故障转移" aria-label="Permalink to &quot;执行故障转移&quot;">​</a></h3><p>领头哨兵按优先级从「从节点」中选出新主节点：</p><ol><li>过滤掉不健康的从节点（下线、断连）</li><li>按 <code>slave-priority</code> 优先级选最高的</li><li>优先级相同时，选复制偏移量最大的（数据最新）</li><li>都相同时，选 runid 最小的</li></ol><p>选出新主后，领头哨兵让其他从节点复制新主，并把原主节点降级为从节点（待其恢复后重新加入）。</p><hr><h2 id="_2-3-配置" tabindex="-1">2.3 配置 <a class="header-anchor" href="#_2-3-配置" aria-label="Permalink to &quot;2.3 配置&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># sentinel.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sentinel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> monitor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mymaster</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 6379</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 监控主节点，quorum=2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sentinel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down-after-milliseconds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mymaster</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 30000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 30 秒无响应判下线</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sentinel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> failover-timeout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mymaster</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 180000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 故障转移超时</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:left;">配置</th><th style="text-align:left;">含义</th></tr></thead><tbody><tr><td style="text-align:left;"><code>monitor</code></td><td style="text-align:left;">指定监控的主节点与 quorum（法定人数）</td></tr><tr><td style="text-align:left;"><code>down-after-milliseconds</code></td><td style="text-align:left;">判定下线的时间阈值</td></tr><tr><td style="text-align:left;"><code>failover-timeout</code></td><td style="text-align:left;">故障转移的超时时间</td></tr></tbody></table><blockquote><p>quorum 是「判定客观下线所需的最少哨兵数」，与「执行转移的哨兵数」是两个概念。哨兵数量一般建议 ≥ 3，且为奇数，避免脑裂时无法达成多数。</p></blockquote><hr><h2 id="_2-4-局限" tabindex="-1">2.4 局限 <a class="header-anchor" href="#_2-4-局限" aria-label="Permalink to &quot;2.4 局限&quot;">​</a></h2><p>哨兵解决了「自动故障转移」，但仍有局限：</p><table tabindex="0"><thead><tr><th style="text-align:left;">局限</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">容量受限</td><td style="text-align:left;">所有节点存全量数据，写仍只能在主节点</td></tr><tr><td style="text-align:left;">无法水平扩展</td><td style="text-align:left;">数据量大时单主内存不够，哨兵无法分片</td></tr><tr><td style="text-align:left;">切换有窗口</td><td style="text-align:left;">故障转移期间短暂不可写</td></tr></tbody></table><p>哨兵解决「高可用」，集群解决「水平扩展」。数据量大到单机装不下时，就要用集群（第 3 章）。</p>`,31)])])}const p=I(s,[["render",g]]);export{r as __pageData,p as default};
